SELECT r."report_id", r."subject_type", r."subject_id", r."can_view", r."can_run", r."can_edit", r."can_publish", r."can_use_dql", r."etag" FROM (SELECT report_acl."report_id", report_acl."subject_type", report_acl."subject_id", report_acl."can_view", report_acl."can_run", report_acl."can_edit", report_acl."can_publish", report_acl."can_use_dql", report_acl."etag", report_acl."should_delete" FROM  (SELECT a.*, '' AS should_delete FROM report_acl a
)  report_acl WHERE 1 = 1) r WHERE $criteria.CompositeIn("r", $AclKeys)
